-- LOCAL PRO ONLY: atomic private duplicate after verified Storage staging.
-- Abort retires reservations, retains tracked private objects; NO physical DELETE.
-- Existing functions/columns are never replaced. Two additive quota/identity guards.
begin;
create table if not exists public.pro_daily_log_duplicates(actor_id uuid not null,actor_name text not null check(length(actor_name)<=160),action_id uuid not null,owner_id uuid not null,work_id text not null,source_log_id uuid not null,target_log_id uuid not null,grant_id uuid,generation uuid,input jsonb not null,source_snapshot jsonb not null,phase text not null default 'pending' check(phase in('pending','finalizing','confirmed','aborted')),result jsonb,reserved_at timestamptz not null default now(),aborted_at timestamptz,primary key(actor_id,action_id),unique(owner_id,work_id,target_log_id),foreign key(owner_id,work_id) references pro_work(user_id,id) on delete cascade,check((grant_id is null)=(generation is null)),check((phase='confirmed')=(result is not null)),check((phase='aborted')=(aborted_at is not null)));
create table if not exists public.pro_daily_log_duplicate_files(actor_id uuid not null,action_id uuid not null,position integer not null check(position between 0 and 19),source_file_id uuid not null,target_file_id uuid not null unique,copy_action_id uuid not null,source_snapshot jsonb not null,source_path text not null,target_path text not null unique,verified boolean not null default false,materialized boolean not null default false,primary key(actor_id,action_id,position),foreign key(actor_id,action_id) references pro_daily_log_duplicates(actor_id,action_id) on delete cascade);
create table if not exists public.pro_daily_log_duplicate_aborts(actor_id uuid not null,action_id uuid not null,duplicate_action_id uuid not null,owner_id uuid not null references profiles(id) on delete cascade,input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id));
create table if not exists public.pro_daily_log_duplicate_retirements(owner_id uuid not null references profiles(id) on delete cascade,owner_name text not null check(length(owner_name)<=160),action_id uuid not null,duplicate_actor_id uuid not null,duplicate_action_id uuid not null,work_id text not null,input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(owner_id,action_id),unique(duplicate_actor_id,duplicate_action_id));
create or replace function public.pro_daily_log_duplicate_validate(p_input jsonb) returns void language plpgsql immutable security invoker set search_path=public,pg_temp as $$declare ref jsonb;begin
 if jsonb_typeof(p_input) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from array['action','actionId','childLogActionId','files','generation','grantId','sourceFileRevision','sourceLogId','sourceRevision','targetLogId','workId'] or p_input->>'action' is distinct from 'duplicate_with_files' or jsonb_typeof(p_input->'files') is distinct from 'array' or jsonb_array_length(p_input->'files') not between 1 and 20 or jsonb_typeof(p_input->'workId') is distinct from 'string' or length(p_input->>'workId') not between 1 and 160 or jsonb_typeof(p_input->'grantId') not in('string','null') or jsonb_typeof(p_input->'generation') not in('string','null') or jsonb_typeof(p_input->'sourceRevision') is distinct from 'number' or jsonb_typeof(p_input->'sourceFileRevision') is distinct from 'number' or not coalesce(p_input->>'sourceRevision'~'^[0-9]{1,10}$',false) or not coalesce(p_input->>'sourceFileRevision'~'^[0-9]{1,10}$',false) then raise exception 'Invalid duplicate body' using errcode='22023';end if;
 if(p_input->>'actionId')::uuid is null or(p_input->>'childLogActionId')::uuid is null or(p_input->>'sourceLogId')::uuid is null or(p_input->>'targetLogId')::uuid is null or p_input->>'sourceLogId'=p_input->>'targetLogId' or (p_input->>'grantId' is null)<>(p_input->>'generation' is null) or(p_input->>'sourceRevision')::numeric not between 1 and 2147483646 or(p_input->>'sourceFileRevision')::numeric not between 0 and 2147483646 then raise exception 'Invalid duplicate identities' using errcode='22023';end if;
 perform (p_input->>'grantId')::uuid,(p_input->>'generation')::uuid;
 for ref in select value from jsonb_array_elements(p_input->'files') loop
 if jsonb_typeof(ref) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(ref)key) is distinct from array['copyActionId','sha256','sourceFileId','targetFileId'] or not coalesce(ref->>'sha256'~'^[a-f0-9]{64}$',false) or(ref->>'sourceFileId')::uuid is null or(ref->>'targetFileId')::uuid is null or(ref->>'copyActionId')::uuid is null then raise exception 'Invalid selected file' using errcode='22023';end if;
 end loop;
 if(select count(distinct value->>'sourceFileId') from jsonb_array_elements(p_input->'files'))<>jsonb_array_length(p_input->'files') or(select count(distinct value->>'targetFileId') from jsonb_array_elements(p_input->'files'))<>jsonb_array_length(p_input->'files') or(select count(distinct x) from(select p_input->>'actionId' x union all select p_input->>'childLogActionId' union all select value->>'copyActionId' from jsonb_array_elements(p_input->'files'))s)<>jsonb_array_length(p_input->'files')+2 or exists(select 1 from jsonb_array_elements(p_input->'files')a cross join jsonb_array_elements(p_input->'files')b where a->>'sourceFileId'=b->>'targetFileId') then raise exception 'Duplicate identity collision' using errcode='22023';end if;
end $$;
create or replace function public.pro_daily_log_duplicate_canonical(p_value jsonb) returns text language plpgsql immutable security invoker set search_path=public,pg_temp as $$declare answer text;begin
 if jsonb_typeof(p_value)='object' then select '{'||coalesce(string_agg(to_jsonb(key)::text||':'||pro_daily_log_duplicate_canonical(value),',' order by key),'')||'}' into answer from jsonb_each(p_value);return answer;
 elsif jsonb_typeof(p_value)='array' then select '['||coalesce(string_agg(pro_daily_log_duplicate_canonical(value),',' order by ord),'')||']' into answer from jsonb_array_elements(p_value) with ordinality x(value,ord);return answer;end if;return p_value::text;end $$;
create or replace function public.pro_daily_log_duplicate_json(p_actor uuid,p_action uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$ select jsonb_build_object('input',d.input,'source',d.source_snapshot,'selectedFiles',coalesce((select jsonb_agg(f.source_snapshot order by f.position) from pro_daily_log_duplicate_files f where f.actor_id=d.actor_id and f.action_id=d.action_id),'[]'::jsonb),'phase',case when d.phase='finalizing' then 'pending' else d.phase end,'verifiedFileIds',coalesce((select jsonb_agg(f.target_file_id order by f.position) from pro_daily_log_duplicate_files f where f.actor_id=d.actor_id and f.action_id=d.action_id and f.verified),'[]'::jsonb),'result',d.result,'reservedAt',d.reserved_at,'abortedAt',d.aborted_at) from pro_daily_log_duplicates d where d.actor_id=p_actor and d.action_id=p_action $$;
create or replace function public.pro_daily_log_duplicate_auth(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare d pro_daily_log_duplicates;ctx jsonb;begin
 if exists(select 1 from pro_daily_log_duplicate_retirements where duplicate_actor_id=p_actor and duplicate_action_id=p_action) then raise exception 'Owner retired this duplicate' using errcode='42501';end if;
 select * into d from pro_daily_log_duplicates where actor_id=p_actor and action_id=p_action;if not found then raise exception 'Duplicate unavailable' using errcode='42501';end if;
 ctx:=pro_daily_log_context(p_actor,d.work_id,d.grant_id,true);if (ctx->>'ownerId')::uuid<>d.owner_id or (ctx->>'sourceInviteId')::uuid is distinct from d.generation then raise exception 'Duplicate access changed' using errcode='42501';end if;
 -- Source visibility remains necessary even for immutable receipts.
 perform pro_daily_log_file_context(p_actor,d.work_id,d.source_log_id,d.grant_id,false,d.generation,true);
 return ctx;end $$;
create or replace function public.pro_daily_log_duplicate_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare aid uuid;a pro_daily_log_duplicate_aborts;ctx jsonb;begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into a from pro_daily_log_duplicate_aborts where actor_id=p_actor and(action_id=p_action or duplicate_action_id=p_action) order by at limit 1;
 if found then
  aid:=a.duplicate_action_id;ctx:=pro_daily_log_context(p_actor,a.input->'duplicate'->>'workId',(a.input->'duplicate'->>'grantId')::uuid,true);
  if(ctx->>'sourceInviteId')::uuid is distinct from(a.input->'duplicate'->>'generation')::uuid then raise exception 'Generation changed' using errcode='42501';end if;
  perform pro_daily_log_file_context(p_actor,a.input->'duplicate'->>'workId',(a.input->'duplicate'->>'sourceLogId')::uuid,(a.input->'duplicate'->>'grantId')::uuid,false,(a.input->'duplicate'->>'generation')::uuid,true);
  return jsonb_build_object('attempt',pro_daily_log_duplicate_json(p_actor,aid),'abort',jsonb_build_object('input',a.input,'at',a.at));
 end if;
 if exists(select 1 from pro_daily_log_duplicate_retirements where duplicate_actor_id=p_actor and duplicate_action_id=p_action) then raise exception 'Owner retired this duplicate' using errcode='42501';end if;
 if not exists(select 1 from pro_daily_log_duplicates where actor_id=p_actor and action_id=p_action) then return jsonb_build_object('attempt',null,'abort',null);end if;
 perform pro_daily_log_duplicate_auth(p_actor,p_action);return jsonb_build_object('attempt',pro_daily_log_duplicate_json(p_actor,p_action),'abort',null);end $$;
create or replace function public.pro_daily_log_duplicate_file_guard() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$declare d pro_daily_log_duplicates;f pro_daily_log_duplicate_files;slots integer;begin
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||new.owner_id::text||':'||new.work_id,0));
 if exists(select 1 from pro_daily_log_duplicate_aborts qa cross join lateral jsonb_array_elements(qa.input->'duplicate'->'files')r where r->>'targetFileId'=new.id::text) then raise exception 'Aborted file identity retired' using errcode='40001';end if;
 select * into f from pro_daily_log_duplicate_files where target_file_id=new.id;
 if found then select * into d from pro_daily_log_duplicates where actor_id=f.actor_id and action_id=f.action_id;
  if current_setting('pro.daily_duplicate',true) is distinct from d.actor_id::text||':'||d.action_id::text or d.phase<>'finalizing' or not f.materialized or new.owner_id<>d.owner_id or new.work_id<>d.work_id or new.log_id<>d.target_log_id or new.created_by<>d.actor_id or new.sha256<>f.source_snapshot->>'sha256' or new.object_path<>f.target_path then raise exception 'Reserved duplicate identity' using errcode='40001';end if;
 end if;
 select count(*) into slots from pro_daily_log_duplicate_files qs join pro_daily_log_duplicates qb using(actor_id,action_id) where qb.owner_id=new.owner_id and qb.work_id=new.work_id and qb.phase in('pending','finalizing') and not qs.materialized;
 if (select count(*) from pro_daily_log_files where owner_id=new.owner_id and work_id=new.work_id)+slots>=100 then raise exception 'File capacity including duplicate reservations exceeded' using errcode='40001';end if;
 return new;end $$;
drop trigger if exists pro_daily_log_duplicate_file_guard on public.pro_daily_log_files;
create trigger pro_daily_log_duplicate_file_guard before insert on public.pro_daily_log_files for each row execute function pro_daily_log_duplicate_file_guard();
create or replace function public.pro_daily_log_duplicate_log_guard() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$declare d pro_daily_log_duplicates;slots integer;own_slot integer:=0;begin
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||new.owner_id::text||':'||new.work_id,0));
 if exists(select 1 from pro_daily_log_duplicate_aborts qa where qa.owner_id=new.owner_id and qa.input->'duplicate'->>'workId'=new.work_id and qa.input->'duplicate'->>'targetLogId'=new.id::text) then raise exception 'Aborted log identity retired' using errcode='40001';end if;
 select * into d from pro_daily_log_duplicates where owner_id=new.owner_id and work_id=new.work_id and target_log_id=new.id;
 if found then
  if(current_setting('pro.daily_duplicate',true) is distinct from d.actor_id::text||':'||d.action_id::text or d.phase<>'finalizing' or new.created_by<>d.actor_id) then raise exception 'Reserved duplicate log identity' using errcode='40001';end if;own_slot:=1;
 end if;
 select count(*) into slots from pro_daily_log_duplicates qb where qb.owner_id=new.owner_id and qb.work_id=new.work_id and qb.phase in('pending','finalizing');
 if(select count(*) from pro_daily_logs where owner_id=new.owner_id and work_id=new.work_id)+slots-own_slot>=500 then raise exception 'Log capacity including reservations exceeded' using errcode='40001';end if;return new;end $$;
drop trigger if exists pro_daily_log_duplicate_log_guard on public.pro_daily_logs;
create trigger pro_daily_log_duplicate_log_guard before insert on public.pro_daily_logs for each row execute function pro_daily_log_duplicate_log_guard();
create or replace function public.pro_daily_log_duplicate_reserve(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;gid uuid;gen uuid;own uuid;wid text;lid uuid;target uuid;ctx jsonb;d pro_daily_log_duplicates;l pro_daily_logs;f pro_daily_log_files;ref jsonb;n integer:=0;slots integer;keytext text;begin
 if jsonb_typeof(p_input) is distinct from 'object' or (select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from array['action','actionId','childLogActionId','files','generation','grantId','sourceFileRevision','sourceLogId','sourceRevision','targetLogId','workId'] or p_input->>'action' is distinct from 'duplicate_with_files' or jsonb_typeof(p_input->'files') is distinct from 'array' or jsonb_array_length(p_input->'files') not between 1 and 20 or jsonb_typeof(p_input->'grantId') not in('string','null') or jsonb_typeof(p_input->'generation') not in('string','null') or jsonb_typeof(p_input->'sourceRevision') is distinct from 'number' or jsonb_typeof(p_input->'sourceFileRevision') is distinct from 'number' or not coalesce(p_input->>'sourceRevision'~'^[0-9]{1,10}$',false) or not coalesce(p_input->>'sourceFileRevision'~'^[0-9]{1,10}$',false) then raise exception 'Invalid duplicate' using errcode='22023';end if;
 perform pro_daily_log_duplicate_validate(p_input);
 aid:=(p_input->>'actionId')::uuid;gid:=(p_input->>'grantId')::uuid;gen:=(p_input->>'generation')::uuid;wid:=p_input->>'workId';lid:=(p_input->>'sourceLogId')::uuid;target:=(p_input->>'targetLogId')::uuid;
 if aid is null or target is null or lid is null or target=lid or (p_input->>'childLogActionId')::uuid is null or (gid is null)<>(gen is null) or (p_input->>'sourceRevision')::numeric not between 1 and 2147483646 or(p_input->>'sourceFileRevision')::numeric not between 0 and 2147483646 then raise exception 'Invalid duplicate identity' using errcode='22023';end if;
 ctx:=pro_daily_log_context(p_actor,wid,gid,true);own:=(ctx->>'ownerId')::uuid;if gen is distinct from(ctx->>'sourceInviteId')::uuid then raise exception 'Generation changed' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-duplicate:'||p_actor::text||':'||aid::text,0));
 -- All child action namespaces before the work advisory, never the reverse.
 for keytext in select k from(select 'pro-daily-log-action:'||p_actor::text||':'||(p_input->>'childLogActionId') k union all select 'pro-daily-log-file-action:'||p_actor::text||':'||(value->>'copyActionId') from jsonb_array_elements(p_input->'files'))s order by k loop perform pg_advisory_xact_lock(hashtextextended(keytext,0));end loop;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||own::text||':'||wid,0));if gid is not null then perform 1 from pro_team_grants where id=gid for share;end if;
 ctx:=pro_daily_log_context(p_actor,wid,gid,true);if gen is distinct from(ctx->>'sourceInviteId')::uuid then raise exception 'Generation changed' using errcode='42501';end if;
 if exists(select 1 from pro_daily_log_duplicate_aborts where actor_id=p_actor and duplicate_action_id=aid) then if exists(select 1 from pro_daily_log_duplicate_aborts where actor_id=p_actor and duplicate_action_id=aid and input->'duplicate' is distinct from p_input) then raise exception 'Duplicate identity reused' using errcode='22023';end if;return null;end if;
 select * into d from pro_daily_log_duplicates where actor_id=p_actor and action_id=aid;
 if found then perform pro_daily_log_duplicate_auth(p_actor,aid);if d.input is distinct from p_input then raise exception 'Duplicate action reused' using errcode='22023';end if;return pro_daily_log_duplicate_json(p_actor,aid);end if;
 if exists(select 1 from pro_daily_log_duplicate_aborts where actor_id=p_actor and action_id=aid) or exists(select 1 from pro_daily_log_actions where actor_id=p_actor and action_id=(p_input->>'childLogActionId')::uuid) then raise exception 'Action identity used' using errcode='40001';end if;
 if exists(select 1 from pro_daily_log_duplicates q where q.actor_id=p_actor and((q.input->>'childLogActionId')::uuid=(p_input->>'childLogActionId')::uuid or exists(select 1 from jsonb_array_elements(p_input->'files')r where r->>'copyActionId'=q.input->>'childLogActionId'))) or exists(select 1 from pro_daily_log_duplicate_files q where q.actor_id=p_actor and(q.copy_action_id=(p_input->>'childLogActionId')::uuid or exists(select 1 from jsonb_array_elements(p_input->'files')r where q.copy_action_id=(r->>'copyActionId')::uuid))) then raise exception 'Reserved child identity reused' using errcode='40001';end if;
 if exists(select 1 from pro_daily_logs where owner_id=own and work_id=wid and id=target) or exists(select 1 from pro_daily_log_duplicates where owner_id=own and work_id=wid and target_log_id=target) then raise exception 'Target identity used' using errcode='40001';end if;
 select * into l from pro_daily_logs where owner_id=own and work_id=wid and id=lid for share;if not found or not pro_daily_log_visible(p_actor,ctx,l) then raise exception 'Source unavailable' using errcode='42501';end if;
 if l.revision<>(p_input->>'sourceRevision')::integer or coalesce((select revision from pro_daily_log_file_heads where owner_id=own and work_id=wid and log_id=lid),0)<>(p_input->>'sourceFileRevision')::integer then raise exception 'Duplicate source changed' using errcode='40001';end if;
 select count(*) into slots from pro_daily_log_duplicate_files qs join pro_daily_log_duplicates qb using(actor_id,action_id) where qb.owner_id=own and qb.work_id=wid and qb.phase in('pending','finalizing') and not qs.materialized;
 if (select count(*) from pro_daily_log_files where owner_id=own and work_id=wid)+slots+jsonb_array_length(p_input->'files')>100 or (select count(*) from pro_daily_logs where owner_id=own and work_id=wid)+(select count(*) from pro_daily_log_duplicates qb where qb.owner_id=own and qb.work_id=wid and qb.phase in('pending','finalizing'))>=500 then raise exception 'Duplicate capacity exceeded' using errcode='40001';end if;
 if (select count(distinct value->>'sourceFileId') from jsonb_array_elements(p_input->'files'))<>jsonb_array_length(p_input->'files') or(select count(distinct value->>'targetFileId') from jsonb_array_elements(p_input->'files'))<>jsonb_array_length(p_input->'files') or(select count(distinct x) from(select aid::text x union all select p_input->>'childLogActionId' union all select value->>'copyActionId' from jsonb_array_elements(p_input->'files'))s)<>jsonb_array_length(p_input->'files')+2 then raise exception 'Duplicate identities' using errcode='22023';end if;
 insert into pro_daily_log_duplicates(actor_id,actor_name,action_id,owner_id,work_id,source_log_id,target_log_id,grant_id,generation,input,source_snapshot)values(p_actor,pro_team_name(p_actor),aid,own,wid,lid,target,gid,gen,p_input,pro_daily_log_json(l));
 for ref in select value from jsonb_array_elements(p_input->'files') loop
  if jsonb_typeof(ref) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(ref)key) is distinct from array['copyActionId','sha256','sourceFileId','targetFileId'] or not coalesce(ref->>'sha256'~'^[a-f0-9]{64}$',false) or(ref->>'sourceFileId')::uuid is null or(ref->>'targetFileId')::uuid is null or(ref->>'copyActionId')::uuid is null then raise exception 'Invalid selected file' using errcode='22023';end if;
  if exists(select 1 from pro_daily_log_files where id=(ref->>'targetFileId')::uuid) or exists(select 1 from pro_daily_log_file_actions where actor_id=p_actor and action_id=(ref->>'copyActionId')::uuid) or exists(select 1 from pro_daily_log_actions where actor_id=p_actor and action_id=(ref->>'copyActionId')::uuid) then raise exception 'Child identity used' using errcode='40001';end if;
  select * into f from pro_daily_log_files where owner_id=own and work_id=wid and log_id=lid and id=(ref->>'sourceFileId')::uuid and ready for share;if not found or f.sha256<>ref->>'sha256' then raise exception 'Selected source changed' using errcode='40001';end if;
  insert into pro_daily_log_duplicate_files values(p_actor,aid,n,f.id,(ref->>'targetFileId')::uuid,(ref->>'copyActionId')::uuid,pro_daily_log_file_json(f),f.object_path,own::text||'/'||(ref->>'targetFileId')||case when f.mime_type='application/pdf' then '.pdf' else '.jpg' end,false,false);n:=n+1;
 end loop;
 perform pro_daily_log_duplicate_auth(p_actor,aid);return pro_daily_log_duplicate_json(p_actor,aid);end $$;
create or replace function public.pro_daily_log_duplicate_stage(p_actor uuid,p_action uuid,p_file uuid default null,p_verified boolean default false) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare d pro_daily_log_duplicates;items jsonb;begin
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-duplicate:'||p_actor::text||':'||p_action::text,0));perform pro_daily_log_duplicate_auth(p_actor,p_action);select * into d from pro_daily_log_duplicates where actor_id=p_actor and action_id=p_action;
 if d.phase<>'pending' then return jsonb_build_object('attempt',pro_daily_log_duplicate_json(p_actor,p_action),'objects','[]'::jsonb);end if;
 if p_verified then update pro_daily_log_duplicate_files set verified=true where actor_id=p_actor and action_id=p_action and target_file_id=p_file;if not found then raise exception 'File unavailable' using errcode='22023';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('fileId',target_file_id,'sourcePath',source_path,'targetPath',target_path,'file',source_snapshot) order by position),'[]'::jsonb) into items from pro_daily_log_duplicate_files where actor_id=p_actor and action_id=p_action;
 perform pro_daily_log_duplicate_auth(p_actor,p_action);return jsonb_build_object('attempt',pro_daily_log_duplicate_json(p_actor,p_action),'objects',items);end $$;
create or replace function public.pro_daily_log_duplicate_finish(p_actor uuid,p_action uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare d pro_daily_log_duplicates;f pro_daily_log_duplicate_files;keytext text;ctx jsonb;copy_input jsonb;log_result jsonb;file_result jsonb;files jsonb:='[]';head integer:=0;answer jsonb;begin
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-duplicate:'||p_actor::text||':'||p_action::text,0));perform pro_daily_log_duplicate_auth(p_actor,p_action);select * into d from pro_daily_log_duplicates where actor_id=p_actor and action_id=p_action;
 if d.phase<>'pending' then return pro_daily_log_duplicate_json(p_actor,p_action);end if;
 for keytext in select k from(select 'pro-daily-log-action:'||p_actor::text||':'||(d.input->>'childLogActionId') k union all select 'pro-daily-log-file-action:'||p_actor::text||':'||copy_action_id::text from pro_daily_log_duplicate_files where actor_id=p_actor and action_id=p_action)s order by k loop perform pg_advisory_xact_lock(hashtextextended(keytext,0));end loop;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||d.owner_id::text||':'||d.work_id,0));if d.grant_id is not null then perform 1 from pro_team_grants where id=d.grant_id for share;end if;perform pro_daily_log_duplicate_auth(p_actor,p_action);
 if exists(select 1 from pro_daily_log_duplicate_files where actor_id=p_actor and action_id=p_action and not verified) then raise exception 'Files not verified' using errcode='40001';end if;
 if coalesce((select revision from pro_daily_log_file_heads where owner_id=d.owner_id and work_id=d.work_id and log_id=d.source_log_id),0)<>(d.input->>'sourceFileRevision')::integer or not exists(select 1 from pro_daily_logs where owner_id=d.owner_id and work_id=d.work_id and id=d.source_log_id and revision=(d.input->>'sourceRevision')::integer) then raise exception 'Source changed before completion' using errcode='40001';end if;
 if exists(select 1 from pro_daily_log_actions where actor_id=p_actor and action_id=(d.input->>'childLogActionId')::uuid) or exists(select 1 from pro_daily_log_duplicate_files qs join pro_daily_log_file_actions qa on qa.actor_id=qs.actor_id and qa.action_id=qs.copy_action_id where qs.actor_id=p_actor and qs.action_id=p_action) then raise exception 'Child action identity used' using errcode='40001';end if;
 perform set_config('pro.daily_duplicate',p_actor::text||':'||p_action::text,true);
 update pro_daily_log_duplicates set phase='finalizing' where actor_id=p_actor and action_id=p_action;
 log_result:=pro_daily_logs_mutate(p_actor,jsonb_build_object('action','duplicate','actionId',d.input->'childLogActionId','workId',d.work_id,'grantId',d.grant_id,'logId',d.source_log_id,'revision',d.input->'sourceRevision','targetLogId',d.target_log_id));
 for f in select * from pro_daily_log_duplicate_files where actor_id=p_actor and action_id=p_action order by position loop
  -- Materialize reservation in the SAME TX; quota guard counts remaining slots only.
  update pro_daily_log_duplicate_files set materialized=true where actor_id=p_actor and action_id=p_action and position=f.position;
  copy_input:=jsonb_build_object('action','copy','actionId',f.copy_action_id,'fileId',f.target_file_id,'workId',d.work_id,'logId',d.target_log_id,'grantId',d.grant_id,'generation',d.generation,'sourceLogId',d.source_log_id,'sourceFileId',f.source_file_id,'sourceSha256',f.source_snapshot->>'sha256');
  perform pro_daily_log_file_reserve(p_actor,copy_input,encode(sha256(convert_to(pro_daily_log_duplicate_canonical(copy_input),'UTF8')),'hex'));
  file_result:=pro_daily_log_file_ready(p_actor,f.copy_action_id);files:=files||jsonb_build_array(file_result->'file');head:=(file_result->>'revision')::integer;
 end loop;
 perform set_config('pro.daily_duplicate','',true);
 answer:=jsonb_build_object('action','duplicate_with_files','log',log_result->'log','files',files,'revision',head);
 update pro_daily_log_duplicates set phase='confirmed',result=answer where actor_id=p_actor and action_id=p_action;perform pro_daily_log_duplicate_auth(p_actor,p_action);return pro_daily_log_duplicate_json(p_actor,p_action);end $$;
-- Tombstones do not require a begin reservation. They close abort-before-begin races.
create or replace function public.pro_daily_log_duplicate_abort(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare inp jsonb;aid uuid;did uuid;keytext text;ctx jsonb;old pro_daily_log_duplicate_aborts;d pro_daily_log_duplicates;begin
 if jsonb_typeof(p_input) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from array['action','actionId','duplicate'] or p_input->>'action' is distinct from 'abort' or jsonb_typeof(p_input->'duplicate') is distinct from 'object' then raise exception 'Invalid abort' using errcode='22023';end if;
 inp:=p_input->'duplicate';perform pro_daily_log_duplicate_validate(inp);aid:=(p_input->>'actionId')::uuid;did:=(inp->>'actionId')::uuid;if aid is null or did is null or aid=did then raise exception 'Invalid abort identity' using errcode='22023';end if;
 ctx:=pro_daily_log_context(p_actor,inp->>'workId',(inp->>'grantId')::uuid,true);if (ctx->>'sourceInviteId')::uuid is distinct from(inp->>'generation')::uuid then raise exception 'Generation changed' using errcode='42501';end if;perform pro_daily_log_file_context(p_actor,inp->>'workId',(inp->>'sourceLogId')::uuid,(inp->>'grantId')::uuid,false,(inp->>'generation')::uuid,true);
 for keytext in select x from unnest(array[did::text,aid::text])x order by x loop perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-duplicate:'||p_actor::text||':'||keytext,0));end loop;
 if exists(select 1 from pro_daily_log_duplicates where actor_id=p_actor and action_id=aid) then raise exception 'Abort identity used' using errcode='40001';end if;
 select * into old from pro_daily_log_duplicate_aborts where actor_id=p_actor and action_id=aid;if found then if old.input is distinct from p_input then raise exception 'Abort identity reused' using errcode='22023';end if;return pro_daily_log_duplicate_read(p_actor,aid);end if;
 select * into old from pro_daily_log_duplicate_aborts where actor_id=p_actor and duplicate_action_id=did;if found then if old.input->'duplicate' is distinct from inp then raise exception 'Duplicate identity reused' using errcode='22023';end if;return jsonb_build_object('attempt',pro_daily_log_duplicate_json(p_actor,did),'abort',jsonb_build_object('input',old.input,'at',old.at));end if;
 select * into d from pro_daily_log_duplicates where actor_id=p_actor and action_id=did;if found then perform pro_daily_log_duplicate_auth(p_actor,did);if d.input is distinct from inp then raise exception 'Duplicate identity reused' using errcode='22023';end if;if d.phase='confirmed' then raise exception 'Duplicate already completed' using errcode='40001';end if;
  perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||d.owner_id::text||':'||d.work_id,0));update pro_daily_log_duplicates set phase='aborted',aborted_at=now() where actor_id=p_actor and action_id=did;
 end if;
 -- No file/object delete, even if an upload ACK was lost. Paths remain quarantined.
 insert into pro_daily_log_duplicate_aborts(actor_id,action_id,duplicate_action_id,owner_id,input,result) values(p_actor,aid,did,(ctx->>'ownerId')::uuid,p_input,'{}');
 perform pro_daily_log_context(p_actor,inp->>'workId',(inp->>'grantId')::uuid,true);return pro_daily_log_duplicate_read(p_actor,aid);end $$;
create or replace function public.pro_daily_log_duplicate_retire_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare r pro_daily_log_duplicate_retirements;begin
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from pro_daily_log_duplicate_retirements where owner_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('retirement',null);end if;perform pro_work_schedule_owner(p_actor,r.work_id);return jsonb_build_object('retirement',r.result);end $$;
create or replace function public.pro_daily_log_duplicate_retire(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$declare d pro_daily_log_duplicates;r pro_daily_log_duplicate_retirements;aid uuid;da uuid;di uuid;wid text;answer jsonb;begin
 if jsonb_typeof(p_input) is distinct from 'object' or(select array_agg(key order by key) from jsonb_object_keys(p_input)key) is distinct from array['action','actionId','duplicateActionId','duplicateActorId','workId'] or p_input->>'action' is distinct from 'retire' then raise exception 'Invalid retirement' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;da:=(p_input->>'duplicateActorId')::uuid;di:=(p_input->>'duplicateActionId')::uuid;wid:=p_input->>'workId';if aid is null or da is null or di is null or aid=di then raise exception 'Invalid retirement identity' using errcode='22023';end if;perform pro_work_schedule_owner(p_actor,wid);
 perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-duplicate-retire:'||p_actor::text||':'||aid::text,0));perform pg_advisory_xact_lock(hashtextextended('pro-daily-log-duplicate:'||da::text||':'||di::text,0));
 select * into r from pro_daily_log_duplicate_retirements where owner_id=p_actor and action_id=aid;if found then if r.input is distinct from p_input then raise exception 'Retirement identity reused' using errcode='22023';end if;return pro_daily_log_duplicate_retire_read(p_actor,aid);end if;
 if exists(select 1 from pro_daily_log_duplicates where actor_id=p_actor and action_id=aid) or exists(select 1 from pro_daily_log_duplicate_aborts where actor_id=p_actor and action_id=aid) then raise exception 'Retirement identity used' using errcode='40001';end if;
 select * into d from pro_daily_log_duplicates where actor_id=da and action_id=di and owner_id=p_actor and work_id=wid;if not found then raise exception 'Pending duplicate unavailable' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));perform pro_work_schedule_owner(p_actor,wid);
 if d.phase<>'pending' then raise exception 'Duplicate is no longer pending' using errcode='40001';end if;
 update pro_daily_log_duplicates set phase='aborted',aborted_at=now() where actor_id=da and action_id=di;
 answer:=jsonb_build_object('input',p_input,'at',now(),'attempt',pro_daily_log_duplicate_json(da,di));insert into pro_daily_log_duplicate_retirements values(p_actor,pro_team_name(p_actor),aid,da,di,wid,p_input,answer,now());perform pro_work_schedule_owner(p_actor,wid);return jsonb_build_object('retirement',answer);end $$;
create or replace function public.pro_daily_log_duplicate_pending(p_actor uuid,p_work text,p_after text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare anchor pro_daily_log_duplicates;items jsonb;cursor_value text;begin
 perform pro_work_schedule_owner(p_actor,p_work);
 if p_after is not null then select * into anchor from pro_daily_log_duplicates where owner_id=p_actor and work_id=p_work and phase='pending' and actor_id=split_part(p_after,':',1)::uuid and action_id=split_part(p_after,':',2)::uuid;if not found then raise exception 'Pending cursor changed' using errcode='40001';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('duplicateActorId',q.actor_id,'duplicateActorName',q.actor_name,'attempt',pro_daily_log_duplicate_json(q.actor_id,q.action_id)) order by q.reserved_at desc,q.actor_id desc,q.action_id desc),'[]'::jsonb) into items from(select * from pro_daily_log_duplicates where owner_id=p_actor and work_id=p_work and phase='pending' and(p_after is null or(reserved_at,actor_id,action_id)<(anchor.reserved_at,anchor.actor_id,anchor.action_id)) order by reserved_at desc,actor_id desc,action_id desc limit 21)q;
 if jsonb_array_length(items)>20 then cursor_value:=(items->19->>'duplicateActorId')||':'||(items->19->'attempt'->'input'->>'actionId');items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_value);end $$;
create or replace function public.pro_daily_log_duplicate_action_guard() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$declare d pro_daily_log_duplicates;begin
 select x.* into d from pro_daily_log_duplicates x where x.actor_id=new.actor_id and((x.input->>'childLogActionId')::uuid=new.action_id or exists(select 1 from pro_daily_log_duplicate_files f where f.actor_id=x.actor_id and f.action_id=x.action_id and f.copy_action_id=new.action_id)) limit 1;
 if found and(d.phase<>'finalizing' or current_setting('pro.daily_duplicate',true) is distinct from d.actor_id::text||':'||d.action_id::text or new.work_id<>d.work_id or new.owner_id<>d.owner_id or new.input->>'logId' not in(d.source_log_id::text,d.target_log_id::text)) then raise exception 'Reserved duplicate child action' using errcode='40001';end if;return new;end $$;
drop trigger if exists pro_daily_log_duplicate_action_guard on public.pro_daily_log_actions;
create trigger pro_daily_log_duplicate_action_guard before insert on public.pro_daily_log_actions for each row execute function pro_daily_log_duplicate_action_guard();
drop trigger if exists pro_daily_log_duplicate_action_guard on public.pro_daily_log_file_actions;
create trigger pro_daily_log_duplicate_action_guard before insert on public.pro_daily_log_file_actions for each row execute function pro_daily_log_duplicate_action_guard();
create or replace function public.pro_daily_log_duplicate_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$begin
 if tg_table_name in('pro_daily_log_duplicate_aborts','pro_daily_log_duplicate_retirements') then raise exception 'Immutable abort receipt' using errcode='42501';end if;
 if tg_table_name='pro_daily_log_duplicate_files' then if(to_jsonb(new)-array['verified','materialized']) is distinct from(to_jsonb(old)-array['verified','materialized']) or old.verified and not new.verified or old.materialized and not new.materialized then raise exception 'Immutable duplicate provenance' using errcode='42501';end if;
 else if(to_jsonb(new)-array['phase','result','aborted_at']) is distinct from(to_jsonb(old)-array['phase','result','aborted_at']) or old.phase not in('pending','finalizing') then raise exception 'Immutable duplicate receipt' using errcode='42501';end if;end if;return new;end $$;
drop trigger if exists pro_daily_log_duplicate_immutable on public.pro_daily_log_duplicates;
create trigger pro_daily_log_duplicate_immutable before update on public.pro_daily_log_duplicates for each row execute function pro_daily_log_duplicate_immutable();
drop trigger if exists pro_daily_log_duplicate_immutable on public.pro_daily_log_duplicate_files;
create trigger pro_daily_log_duplicate_immutable before update on public.pro_daily_log_duplicate_files for each row execute function pro_daily_log_duplicate_immutable();
drop trigger if exists pro_daily_log_duplicate_immutable on public.pro_daily_log_duplicate_aborts;
create trigger pro_daily_log_duplicate_immutable before update on public.pro_daily_log_duplicate_aborts for each row execute function pro_daily_log_duplicate_immutable();
drop trigger if exists pro_daily_log_duplicate_immutable on public.pro_daily_log_duplicate_retirements;
create trigger pro_daily_log_duplicate_immutable before update on public.pro_daily_log_duplicate_retirements for each row execute function pro_daily_log_duplicate_immutable();
do $$declare t text;f record;begin
 foreach t in array array['pro_daily_log_duplicates','pro_daily_log_duplicate_files','pro_daily_log_duplicate_aborts','pro_daily_log_duplicate_retirements'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on table public.%I from public,anon,authenticated',t);execute format('grant all on table public.%I to service_role',t);end loop;
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro_daily_log_duplicate_%' loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;
end $$;
commit;
